-- Documents V1 D5 — QA Shared household + Processing BASELINE census (read-only).
-- Purpose: org-wide row counts in QA Shared (4acc9386-…) of the CRM household tables, documents, versions, subjects and
--   Processing cases/sources, taken BEFORE the D5 hosted fixture is ensured. The residue census
--   (d5-household-residue-census.sql) must measure the same counts after the reset.
-- A table without org_id (or absent) reports -1; counts go through query_to_xml so the statement is guarded by the
--   catalog and never names a column that does not exist.
select 'd5_household_baseline'::text as question_id, 'data'::text as kind,
       json_build_object(
               'org', '4acc9386-c485-486f-aa1f-05d83499d142',
               'customers', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'customers' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.customers where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'persons', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'persons' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.persons where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'customer_persons', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'customer_persons' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.customer_persons where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'customer_members', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'customer_members' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.customer_members where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'contacts', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'contacts' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.contacts where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'customer_member_contacts', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'customer_member_contacts' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.customer_member_contacts where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'opportunity_persons', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'opportunity_persons' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.opportunity_persons where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'opportunity_customer_members', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'opportunity_customer_members' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.opportunity_customer_members where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'person_child_relationships', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'person_child_relationships' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.person_child_relationships where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'opportunities', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'opportunities' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.opportunities where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'documents', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'documents' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.documents where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'document_versions', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'document_versions' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.document_versions where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'document_subjects', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'document_subjects' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.document_subjects where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'processing_cases', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'processing_cases' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.processing_cases where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1),
               'processing_case_sources', coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'processing_case_sources' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.processing_case_sources where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1)
       )::text as payload;
